def ic(n, s=20): return f'<svg width="{s}" height="{s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{IC[n]}</svg>'
def ed(nm, h): return f'<div class="ed" data-nm="{nm}">{h}</div>'

