def page(slug, t, lay, fkey, nm):
    sk = t['sector']; im, sad, svc, brands, h1, lead = S[sk]
    b64 = base64.b64encode(open(os.path.join(IMG, im + '.jpg'), 'rb').read()).decode()
    d, a, s, r = t['dark'], t['accent'], t['soft'], t['radius']
    def _l(h): return 0.299*int(h[1:3],16)+0.587*int(h[3:5],16)+0.114*int(h[5:7],16)
    if _l(s) < 200:  # koyu 'soft' -> vurgunun çok açık tonu
        s = '#%02x%02x%02x' % tuple(int(255-(255-int(a[i:i+2],16))*0.10) for i in (1,3,5))
    # vurgu üzerindeki yazı: açık vurguda koyu, koyu vurguda beyaz
    lum = lambda h: (0.299 * int(h[1:3], 16) + 0.587 * int(h[3:5], 16) + 0.114 * int(h[5:7], 16))
    ac = '#111' if lum(a) > 150 else '#fff'
    tel = '0532 000 00 00'; init = nm[0]
    links = ['Hizmetler', 'Markalar', 'Hizmet bölgeleri', 'Hakkımızda', 'İletişim']
    form = f'<div class="f"><h3>Hızlı randevu</h3><p>2 dakikada doldurun, sizi arayalım.</p><div>Adınız soyadınız</div><div class="r2"><div>Telefon</div><div>İlçe</div></div><div>Sorun nedir? (isteğe bağlı)</div><a class="btn">Randevu talep et</a></div>'
    logo = f'<a class="lg"><span class="lm">{init}</span>{nm}</a>'
    top = ed('Üst şerit', f'<div class="top"><div class="w"><span>Pzt–Cmt 08:30–19:00 · Acil için 7/24 arayın</span><span>info@firma.com · {tel}</span></div></div>')
    nav = ed('Menü', f'<header class="nav"><div class="w">{logo}<nav>{"".join(f"<a>{x}</a>" for x in links)}<a style="color:var(--a);font-weight:800" href="__PORTAL_URL__">Müşteri portalı</a></nav><a class="btn">{ic("tel",18)} Randevu al</a><label class="bg" for="mn" aria-label="Menü"><i></i></label></div></header>')
    drw = ed('Mobil menü', f'<div class="drw"><div class="dh">{logo}<label class="x" for="mn">✕</label></div><div class="dl">{"".join(f"<a>{x}<em>›</em></a>" for x in links)}<a href="__PORTAL_URL__">Müşteri portalı<em>›</em></a></div><div class="dq"><b>HİZMETLERİMİZ</b>{"".join(f"<span>{x}</span>" for x in svc)}</div><div class="dc"><a class="btn">{ic("tel",18)} {tel} · Ara</a><a class="btn o">WhatsApp ile yaz</a></div><div class="dn">{ic("cl",15)} Hafta içi 08:30 – 19:00 · Cumartesi 09:00 – 17:00<br>{ic("pin",15)} Atatürk Cad. No:12 / İzmir</div></div>')
    mbar = ed('Mobil bar', f'<div class="mbar"><a>{ic("tel",18)} Ara</a><a>{ic("wa",18)} WhatsApp</a><a>Randevu al</a></div>')
    portal = ed('Portal şeridi', f'<section class="pband"><div class="w"><div><b>Servisinizi takip edin, ödemenizi online yapın</b><span>Telefon numaranızla giriş yapın; servis durumunuzu, teklifinizi ve ödemenizi görün.</span></div><a class="btn" href="__PORTAL_URL__">Müşteri portalına gir</a></div></section>')
    foot = ed('Alt bilgi', f'<footer class="ft"><div class="w"><div><b>{nm}</b>Atatürk Cad. No:12<br>İzmir<br>Vergi No: [firma bilgisi]</div><div><b>Hizmetler</b>{"".join(f"<div>{x}</div>" for x in svc[:4])}</div><div><b>Kurumsal</b><div>Hakkımızda</div><div>Hizmet bölgeleri</div><div>KVKK</div><div>İletişim</div></div><div><b>Çalışma saatleri</b><div>Hafta içi 08:30 – 19:00</div><div>Cumartesi 09:00 – 17:00</div><div>Acil: 7/24</div></div><div class="cp">© 2026 {nm} · Bu site OnlineKaydet ile yayınlanır</div></div></footer>')
    svc_cards = ed('Hizmetler', f'<section class="sec"><div class="w"><h2>Hizmetlerimiz</h2><div class="sub">Sorununuzu seçin; süre ve ücret aralığını önceden söyleriz.</div><div class="cards">{"".join(f"<div class=card><div class=n>{i+1}</div><b>{x}</b><span>Randevu ile aynı gün veya ertesi gün.</span></div>" for i,x in enumerate(svc))}</div></div></section>')
    how = ed('Nasıl çalışıyoruz', f'<section class="sec alt"><div class="w"><h2>Nasıl çalışıyoruz?</h2><div class="sub">Dört adımda, her adımda size bilgi verilir.</div><div class="cards">{"".join(f"<div class=card><div class=n>{i+1}</div><b>{x}</b><span>{y}</span></div>" for i,(x,y) in enumerate([("Kayıt","Talebinizi alır, size iş numarası veririz."),("Usta yola çıkar","Randevu saatinde SMS ile haber verilir."),("Onarım","Arıza yerinde tespit edilir, onay sonrası yapılır."),("Teslim","İmzalı servis fişi ve garanti belgesi SMS ile gelir.")]))}</div></div></section>')
    rev = ed('Yorumlar', f'<section class="sec"><div class="w"><h2>Müşterilerimiz ne diyor?</h2><div class="sub">Örnek yorumlar; kendi müşteri yorumlarınızla değiştirin.</div><div class="cards">{"".join(f"<div class=card><b>★★★★★ {n}</b><span>{y}</span></div>" for n,y in [("Ayşe Y.","Randevu saatinde geldi, arızayı gösterip fiyatı baştan söyledi."),("Mehmet K.","Aynı gün çözdüler, servis fişi telefonuma geldi."),("Selin D.","Temiz çalıştılar, garanti belgesini verdiler.")])}</div></div></section>')
    faq = ed('Sık sorulanlar', f'<section class="sec alt"><div class="w faq"><h2>Sık sorulan sorular</h2><div class="sub"></div>{"".join(f"<details><summary>{q}</summary><p>{y}</p></details>" for q,y in [("Fiyatı önceden öğrenebilir miyim?","Evet; arıza tespitinden sonra, onarım başlamadan fiyat söylenir."),("Parçalara garanti var mı?","Takılan parça ve işçilik için yazılı garanti verilir."),("Hangi bölgelere hizmet veriyorsunuz?","Hizmet bölgeleri sayfasındaki ilçelere gidiyoruz.")])}</div></section>')
    pic = lambda cls='', p='center', extra='': f'<div class="pic {cls}" style="--p:{p};{extra}"></div>'
    # --- düzenler
